CREATE TABLE enterprises(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES user(id),created_at INTEGER NOT NULL);
CREATE TABLE departments(id TEXT PRIMARY KEY,enterprise_id TEXT NOT NULL REFERENCES enterprises(id) ON DELETE CASCADE,name TEXT NOT NULL,UNIQUE(enterprise_id,name));
CREATE TABLE members(enterprise_id TEXT NOT NULL REFERENCES enterprises(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES user(id),role TEXT NOT NULL CHECK(role IN('owner','admin','member')),department_id TEXT REFERENCES departments(id),created_at INTEGER NOT NULL,PRIMARY KEY(enterprise_id,user_id));
CREATE INDEX members_user ON members(user_id);
CREATE TABLE invitations(id TEXT PRIMARY KEY,enterprise_id TEXT NOT NULL REFERENCES enterprises(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','member')),department_id TEXT REFERENCES departments(id),expires_at INTEGER NOT NULL,accepted_by TEXT REFERENCES user(id),revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES user(id),enterprise_id TEXT REFERENCES enterprises(id),title TEXT NOT NULL,native_id TEXT,created_at INTEGER NOT NULL);
CREATE INDEX projects_owner ON projects(owner_id,created_at);
CREATE INDEX projects_enterprise ON projects(enterprise_id,created_at);
CREATE TABLE resources(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES user(id),enterprise_id TEXT REFERENCES enterprises(id),kind TEXT NOT NULL CHECK(kind IN('skill','plugin','attachment')),visibility TEXT NOT NULL CHECK(visibility IN('private','enterprise','public')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',version TEXT NOT NULL DEFAULT '1.0.0',storage_key TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX resources_scope ON resources(enterprise_id,kind,created_at);
CREATE TABLE shares(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES user(id),project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,transcript TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('selected','enterprise')),revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE share_members(share_id TEXT NOT NULL REFERENCES shares(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES user(id),role TEXT NOT NULL CHECK(role IN('view','comment')),PRIMARY KEY(share_id,user_id));
CREATE TABLE comments(id TEXT PRIMARY KEY,share_id TEXT NOT NULL REFERENCES shares(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES user(id),content TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX comments_share ON comments(share_id,created_at);
CREATE TABLE plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN('points','membership')),amount INTEGER NOT NULL CHECK(amount>=0),currency TEXT NOT NULL,points INTEGER NOT NULL CHECK(points>=0),days INTEGER NOT NULL CHECK(days>=0),enabled INTEGER NOT NULL DEFAULT 1,apple_product_id TEXT UNIQUE,created_at INTEGER NOT NULL,points_cost INTEGER CHECK(points_cost>0));
CREATE TABLE orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),plan_id TEXT NOT NULL REFERENCES plans(id),provider TEXT NOT NULL,provider_id TEXT UNIQUE,status TEXT NOT NULL CHECK(status IN('pending','paid','refunded','failed')),amount INTEGER NOT NULL,currency TEXT NOT NULL,points INTEGER NOT NULL,days INTEGER NOT NULL,created_at INTEGER NOT NULL,paid_at INTEGER);
CREATE INDEX orders_user ON orders(user_id,created_at);
CREATE TABLE ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),amount INTEGER NOT NULL,balance_after INTEGER NOT NULL,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,actor_id TEXT REFERENCES user(id),created_at INTEGER NOT NULL);
CREATE INDEX ledger_user ON ledger(user_id,created_at);
CREATE TABLE entitlements(order_id TEXT PRIMARY KEY REFERENCES orders(id),user_id TEXT NOT NULL REFERENCES user(id),plan_id TEXT NOT NULL REFERENCES plans(id),starts_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE INDEX entitlements_user ON entitlements(user_id,expires_at);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT REFERENCES user(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at INTEGER NOT NULL);
